<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderOidcDiscoveryUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderOidcDiscoveryUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withOidcDiscoveryUrl,
 * getOidcDiscoveryUrl/oidcDiscoveryUrl accessors, and isOidcDiscoveryUrlChanged with/without original.
 */
class TenantLoginProviderOidcDiscoveryUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withOidcDiscoveryUrl creates a new instance with the OidcDiscoveryUrl set
     * from a string value, and getOidcDiscoveryUrl returns the primitive string.
     */
    public function testWithOidcDiscoveryUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcDiscoveryUrlAccessorUnitTest();

        // Act
        $result = $holder->withOidcDiscoveryUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getOidcDiscoveryUrl());
    }
    /**
     * Asserts that withoidcDiscoveryUrl has access to the value object
     * from a string value, and getOidcDiscoveryUrl returns the primitive string.
     */
    public function testWithOidcDiscoveryUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcDiscoveryUrlAccessorUnitTest();

        // Act
        $result = $holder->withOidcDiscoveryUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->oidcDiscoveryUrl()->value());
    }
    public function testChangedOidcDiscoveryUrl(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcDiscoveryUrlAccessorUnitTest();
        $original = $holder->withOidcDiscoveryUrl('one');
        $same = $holder->withOidcDiscoveryUrl('one');
        $modified = $holder->withOidcDiscoveryUrl('other');

        // Act
        $unchanged = $holder->isOidcDiscoveryUrlChanged();
        $withSame = $original->isOidcDiscoveryUrlChanged($same);
        $withDiferent = $original->isOidcDiscoveryUrlChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderOidcDiscoveryUrlAccessorUnitTest
{
    use TenantLoginProviderOidcDiscoveryUrlAccessor;
}
